CREATE TABLE hakim.article_versions (
    id text NOT NULL,
    article_id text NOT NULL,
    document_version_id text,
    version integer NOT NULL,
    title text,
    body text NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone,
    CONSTRAINT article_versions_check CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT article_versions_version_check CHECK ((version >= 1))
);


--
-- Name: article_version_at(text, timestamp with time zone); Type: FUNCTION; Schema: hakim; Owner: -
--

CREATE FUNCTION hakim.article_version_at(p_article_id text, p_at timestamp with time zone) RETURNS hakim.article_versions
    LANGUAGE sql STABLE
    AS $$
    SELECT *
    FROM article_versions
    WHERE article_id = p_article_id
      AND valid_from <= p_at
      AND (valid_until IS NULL OR p_at < valid_until)
    LIMIT 1;
$$;


